<?php

namespace Database\Seeders;

use App\Models\CareerDetails;
use Illuminate\Database\Seeder;

class TrendingCareersSeeder extends Seeder
{
    public function run(): void
    {
        $existing = CareerDetails::pluck('title')->map(fn ($t) => mb_strtolower(trim($t)))->flip();
        $added = 0;

        foreach (self::careers() as $c) {
            if ($existing->has(mb_strtolower($c[0]))) {
                continue;
            }

            [$title, $match, $demand, $growth, $icon, $flex, $salary, $timeline, $openings, $experience,
                $description, $overview, $skills, $roadmap, $courses] = $c;

            CareerDetails::create([
                'title'         => $title,
                'match'         => $match . '% Match',
                'demand'        => $demand,
                'growth'        => $growth,
                'icon'          => $icon,
                'flexibility'   => $flex,
                'salary'        => $salary,
                'timeline'      => $timeline,
                'openings'      => $openings,
                'experience'    => $experience,
                'description'   => $description,
                'role_overview' => $overview,
                'skills'        => array_map(fn ($s) => ['name' => $s[0], 'value' => $s[1]], $skills),
                'roadmap'       => array_map(fn ($r) => ['title' => $r[0], 'desc' => $r[1], 'duration' => $r[2], 'tags' => $r[3]], $roadmap),
                'courses'       => array_map(fn ($k) => ['title' => $k[0], 'platform' => $k[1], 'rating' => $k[2], 'cost' => $k[3]], $courses),
            ]);
            $added++;
        }

        $this->command?->info("Added {$added} new careers.");
    }

